computeFn:
const price = Number(vehiclePrice) || 0;
const down = Number(downPayment) || 0;
const principal = Math.max(0, price - down);
const r = (Number(annualRatePct) || 0) / 100 / 12;
const n = (Number(loanYears) || 1) * 12;
const monthly = r > 0 ? (principal * r) / (1 - Math.pow(1 + r, -n)) : principal / n;
const totalPaid = monthly * n;
const totalInterest = totalPaid - principal;
const interestRatio = principal > 0 ? (totalInterest / principal) * 100 : 0;
return { interestRatio, monthly, totalInterest, principal };
